    "glsl": "vec4 transition (vec2 uv) {\n  vec2 newUV = uv;\n  newUV.x -= progress;\n  if(uv.x >= progress)\n  {\n    return getFromColor(newUV);\n  }\n\n  \n  return mix(\n    getFromColor(uv),\n    getToColor(uv),\n    progress\n  );\n}",
